# =====================================================================
# NaijaDrops Fix Script - generated by Claude
# Fixes in this batch:
#   1. Vendor-side live rider location on the tracking map (DB RLS fix -
#      already applied directly to Supabase; no file change needed for
#      this part, but the tracking page now also carries last_seen_at
#      through so the map can show a "signal delayed" state).
#   2. Real 3-way messaging: vendor <-> rider <-> customer, with tabs to
#      switch threads (OrderChat.jsx rewritten, new anonymous customer
#      chat API route, ChatNotificationListener field-name bug fixed).
#   3. Rider "Order notes" quick-access panel (both pickup + dropoff
#      notes visible any time, not just during the matching leg).
#   4. Tracking-link Share button now gated on payment_status = 'paid',
#      and moved to the top of the page as the "next step" prompt.
#   5. Vendor negotiation entry point surfaced on the payment-required
#      card; rider negotiation already worked and is unchanged/confirmed.
#   6. DriverHeartbeat retry/backoff + localStorage caching for rider
#      location resilience on low-quality connections.
#   7. Two live bugs fixed: send-package/confirm's dead /track/ redirect
#      (404 after payment) and its rider lookup querying the wrong column.
#
# Run this from the ROOT of your NaijaDrops project folder
# (the folder that contains "src", "package.json", etc.)
#
# Usage:
#   powershell -ExecutionPolicy Bypass -File .\Fix-NaijaDrops-Messaging-Tracking.ps1
# =====================================================================

$ErrorActionPreference = "Stop"
$ts = Get-Date -Format "yyyyMMdd_HHmmss"
$root = Get-Location

function Write-FileNoBom {
    param([string]$RelativePath, [string]$Base64Content)

    $fullPath = Join-Path $root $RelativePath
    $dir = Split-Path $fullPath -Parent

    if (-not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
        Write-Host "  Created directory: $dir" -ForegroundColor DarkGray
    }

    if (Test-Path -LiteralPath $fullPath) {
        $backupPath = "$fullPath.bak_$ts"
        Copy-Item -LiteralPath $fullPath -Destination $backupPath -Force
        Write-Host "  Backed up existing file to: $(Split-Path $backupPath -Leaf)" -ForegroundColor DarkGray
    }

    $bytes = [System.Convert]::FromBase64String($Base64Content)
    $text = [System.Text.Encoding]::UTF8.GetString($bytes)
    $noBomUtf8 = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($fullPath, $text, $noBomUtf8)

    Write-Host "  Wrote: $RelativePath" -ForegroundColor Green
}

Write-Host ""
Write-Host "NaijaDrops fix script starting..." -ForegroundColor Cyan
Write-Host "Project root: $root" -ForegroundColor Cyan
Write-Host ""

# Remove the orphaned, corrupted LocationNoteSection.jsx component.
# It is not imported anywhere (send-package/step-1 defines its own local
# version of the same name), and the file on disk is literally broken -
# every quote in it is escaped with a stray backslash, which is invalid
# JS. It was dead code either way; this just cleans it up rather than
# leaving a landmine for later.
$deadFile = Join-Path $root "src\components\LocationNoteSection.jsx"
if (Test-Path -LiteralPath $deadFile) {
    $deadBackup = "$deadFile.bak_$ts"
    Copy-Item -LiteralPath $deadFile -Destination $deadBackup -Force
    Remove-Item -LiteralPath $deadFile -Force
    Write-Host "Removed unused/corrupted src\components\LocationNoteSection.jsx (backed up first)" -ForegroundColor Yellow
    Write-Host ""
}

